var numbers = [3, 56, 2, 48, 5];

// 0. named function declaration
function square(x) {
  return x * x;
}

// 1. anonymous function passed to map
numbers.map(function (x) { return x * x; });

// 2. arrow with braces and explicit return
numbers.map((x) => { return x * x; });

// 3. single parameter, implicit return
numbers.map(x => x * x); // [9, 3136, 4, 2304, 25]

// arrow stored in a variable
const squareArrow = x => x * x;

// two parameters need parentheses
const product = (x, y) => x * y;

const doubled = numbers.map(x => x * 2);
const small = numbers.filter(num => num < 10);
const total = numbers.reduce((accumulator, currentNumber) => accumulator + currentNumber);
const firstBig = numbers.find(num => num > 10);
const firstBigIndex = numbers.findIndex(num => num > 10);

import Entry from "./components/Entry";
import emojipedia from "./emojipedia";

function App() {
  return (
    <div>
      <h1><span>emojipedia</span></h1>
      <dl className="dictionary">
        {emojipedia.map(emojiTerm => (
          <Entry
            key={emojiTerm.id}
            emoji={emojiTerm.emoji}
            name={emojiTerm.name}
            description={emojiTerm.meaning}
          />
        ))}
      </dl>
    </div>
  );
}

export default App;
